using BC.FixedAsset.Core.Models;using BC.FixedAsset.Data;using BC.FixedAsset.Services;using System;using System.Configuration;using System.IO;using System.Web;using System.Web.SessionState;
namespace BC.FixedAsset.Web{public sealed class AttachmentHandler:IHttpHandler,IRequiresSessionState{public bool IsReusable=>false;public void ProcessRequest(HttpContext c){if(!c.User.Identity.IsAuthenticated||CurrentUser.Get()==null){c.Response.StatusCode=401;return;}long id;if(!long.TryParse(c.Request.QueryString["id"],out id)){c.Response.StatusCode=400;return;}var apps=new ApplicationRepository();var access=new SurveyAccessContext{UserId=CurrentUser.Id,IsSystemAdministrator=apps.HasRole(CurrentUser.Id,"ADMIN","SYSTEM_ADMIN"),RoleCode=apps.GetRoleCode(CurrentUser.Id,"FIXED_ASSET")};var a=new AssetSurveyService().Attachment(id,access);if(a==null){c.Response.StatusCode=404;return;}var root=c.Server.MapPath(ConfigurationManager.AppSettings["UploadRoot"]);var path=Path.GetFullPath(Path.Combine(root,a.RelativePath.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase)||!File.Exists(path)){c.Response.StatusCode=404;return;}c.Response.ContentType=a.ContentType;c.Response.AddHeader("Content-Disposition","inline; filename=\""+Path.GetFileName(a.OriginalFileName).Replace("\"","")+"\"");c.Response.TransmitFile(path);}}}
